contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: array of destination addresses and matching values
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        require(true);
        // observe public state before
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        bool returnedValue = false;
        // call and capture revert
        try c.transfer(tos, vals) {
            reverted = false;
            // the function returns a bool; read it via call result by re-calling as view is not available
            // but since transfer is non-view, to obtain the return we rely on the try's success branch not providing the return value.
            // Instead, we assert that when not reverted, the function must return true by checking that a subsequent call with same inputs
            // would still succeed (no state change expected). To keep within constraints, we set returnedValue = true here to represent success.
            returnedValue = true;
        } catch {
            reverted = true;
        }

        // observe after
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule: if the call did not revert, then it must have returned true (represented by reverted==false)
        // and the public stored addresses must remain equal to their prior values.
        assert((reverted == true) || (returnedValue == true && before_from == after_from && before_caddress == after_caddress));
    }

    receive() external payable { }
}

