contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test invokes transfer with controlled inputs and asserts that when called
    // by the stored c.from (observed via the public getter), a non-reverting call returns true.
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        // require non-empty and matching lengths to hit the main loop in transfer
        require(tos.length > 0 && tos.length == vals.length);

        // we must call c.transfer as if msg.sender == c.from. The checker deploys a fresh c
        // and then calls run once; here we can only call c.transfer from this contract.
        // So ensure the test only asserts the property conditional on c.from being this contract.
        address from = c.from();
        // Only proceed to check the behavior when this InvMutTest contract equals c.from.
        // Otherwise we cannot simulate being the authorized caller, so require false to skip.
        require(from == address(this));

        bool reverted = false;
        bool ret = false;
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        // General rule: when caller is authorized and inputs are non-empty with matching lengths,
        // either the call reverts or it returns true. (non-reverting implies true)
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

