contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Provide non-empty arrays with equal lengths and ensure each v[i] when multiplied by 1e18 does not overflow
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        require(_tos.length > 0 && _tos.length == v.length);
        // ensure multiplication by 1e18 is safe for each element: either v[i]==0 or (v[i]*1e18)/v[i]==1e18
        for (uint i = 0; i < v.length; i++) {
            require(v[i] == 0 || ((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000);
        }

        address beforeFrom = c.from();
        address beforeCaddr = c.caddress();

        bool reverted;
        bool returnedTrue;
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            returnedTrue = r;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        // General rule: either the call reverted, or it returned true and the public getters remained unchanged
        assert(reverted || (returnedTrue && c.from() == beforeFrom && c.caddress() == beforeCaddr));
    }

    receive() external payable {}
}

